// Blocks of the resources section: downloadable PDF list and the online detection report (PG-072A).
// The static PDFs are generated by tools/build-pdfs.mjs from js/pdf-docs.js; the online form is enhanced by js/detect.js.
import { PDF_DOCS, detectionForm, DOC_VERSION, DOC_DATE, CONTACT } from '../js/pdf-docs.js';

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const heading = (b, id) => (b.h2 ? `<h2 id="${id}">${esc(b.h2)}</h2>` : '');
export const pdfHref = file => '/assets/pdf/' + file;

const DL = {
  es: { open: 'Descargar PDF', meta: 'PDF · A4 · versión', free: 'Sin registro; se descarga directamente.' },
  en: { open: 'Download PDF', meta: 'PDF · A4 · version', free: 'No registration; downloads directly.' },
};
const DL_DESC = {
  prep: { es: 'Lista de comprobación para preparar la vivienda antes del tratamiento: ropa, cama, fundas y qué te indicará el técnico.', en: 'Checklist to prepare your home before the treatment: clothing, bed, encasements and what the technician will tell you.' },
  after: { es: 'Qué hacer tras el tratamiento: seguridad y reentrada, seguimiento y qué hacer si vuelven a aparecer indicios.', en: 'What to do after the treatment: safety and re-entry, follow-up and what to do if signs reappear.' },
  recognise: { es: 'Lista para reconocer chinches de cama: qué buscar, dónde mirar y cómo fotografiar lo que encuentres.', en: 'Checklist for recognising bed bugs: what to look for, where to look and how to photograph what you find.' },
  apartments: { es: 'Guía de comprobación para gestores de apartamentos turísticos: entre huéspedes, ante una queja y en edificios con varias unidades.', en: 'Check guide for holiday-apartment managers: between guests, on a complaint and in buildings with several units.' },
  detection: { es: 'Parte de detección en blanco para imprimir y rellenar a mano (también puedes rellenarlo online).', en: 'Blank detection report to print and fill in by hand (you can also fill it in online).' },
  log: { es: 'Hoja con 12 filas para anotar tus propias revisiones: fecha, unidad, zona, resultado y observaciones.', en: 'A 12-row sheet to note your own checks: date, unit, area, result and notes.' },
};
export function downloadsBlock(ctx, b, id) {
  const { lang } = ctx, t = DL[lang];
  const items = PDF_DOCS.filter(d => !b.ids || b.ids.includes(d.id));
  return `<section class="sx-block sx-downloads">${heading(b, id)}${b.intro ? `<p>${b.intro}</p>` : ''}<ul class="sx-dl">${items.map(d => `<li><div><h3>${esc(d[lang].title)}</h3><p>${esc(DL_DESC[d.id][lang])}</p><small>${esc(t.meta)} ${DOC_VERSION} · ${esc(t.free)}</small></div><a class="button yellow" href="${pdfHref(d[lang].file)}" download data-track="pdf_download" data-doc="${d.id}">${esc(t.open)}</a></li>`).join('')}</ul></section>`;
}

const DF = {
  es: { h: 'Parte de detección online', privacy: 'Lo que escribes se queda en tu dispositivo: no se envía ni se guarda en ningún servidor ni se comparte con herramientas de analítica. WhatsApp solo se abre cuando pulsas el botón, y el mensaje no se envía hasta que lo envías tú.', wa: 'Enviar por WhatsApp', pdf: 'Guardar PDF rellenado', print: 'Imprimir', share: 'Compartir el PDF…', blank: 'Descargar PDF en blanco', empty: 'Rellena al menos un campo o marca un indicio.', phoneBad: 'Revisa el teléfono: usa solo números, espacios, + y guiones (entre 6 y 16 dígitos).', dateBad: 'Revisa la fecha y la hora.', reset: 'Borrar todo',
    helpH: 'Cómo enviar el PDF y las fotos por WhatsApp', help: ['Pulsa «Guardar PDF rellenado»: se descarga en tu dispositivo.', 'Pulsa «Enviar por WhatsApp»: se abre la conversación con el texto ya escrito (no se envía hasta que lo envíes tú).', 'En WhatsApp usa el clip (adjuntar): elige «Documento» para el PDF y «Galería» para las fotos de los indicios, y envía.'], helpShare: 'En tu móvil puedes usar «Compartir el PDF…» para mandar el archivo directamente a WhatsApp u otra aplicación.', pbr: 'Un enlace de WhatsApp no puede adjuntar por sí solo el PDF ni las fotos: los adjuntas tú.', filename: 'parte-de-deteccion-chinches-rellenado.pdf', signs: 'Indicios observados', msgAsk: 'Hola, quiero informar de estos indicios y pedir orientación.' },
  en: { h: 'Online detection report', privacy: 'What you type stays on your device: it is not sent to or stored on any server, nor shared with analytics tools. WhatsApp only opens when you press the button, and the message is not sent until you send it yourself.', wa: 'Send on WhatsApp', pdf: 'Save filled-in PDF', print: 'Print', share: 'Share the PDF…', blank: 'Download blank PDF', empty: 'Fill in at least one field or tick a sign.', phoneBad: 'Check the phone number: use only digits, spaces, + and hyphens (6 to 16 digits).', dateBad: 'Check the date and time.', reset: 'Clear all',
    helpH: 'How to send the PDF and photos on WhatsApp', help: ['Press “Save filled-in PDF”: it downloads to your device.', 'Press “Send on WhatsApp”: the chat opens with the text already written (it is not sent until you send it).', 'In WhatsApp use the paperclip (attach): choose “Document” for the PDF and “Gallery” for the photos of the signs, and send.'], helpShare: 'On your phone you can use “Share the PDF…” to send the file directly to WhatsApp or another app.', pbr: 'A WhatsApp link cannot attach the PDF or photos by itself: you attach them yourself.', filename: 'bed-bug-detection-report-filled.pdf', signs: 'Signs observed', msgAsk: 'Hello, I would like to report these signs and ask for guidance.' },
};
export function detectForm(ctx, b, id) {
  const { lang } = ctx, t = DF[lang], F = detectionForm[lang];
  const towns = ctx.prices.travel.towns.map(x => `<option value="${esc(x.town)}"></option>`).join('');
  const defs = [['datetime', 'datetime-local', 'off'], ['property', 'text', 'off'], ['unit', 'text', 'off'], ['reporter', 'text', 'name'], ['town', 'text', 'address-level2'], ['phone', 'tel', 'tel']];
  const doc = PDF_DOCS.find(d => d.id === 'detection')[lang];
  const fields = defs.map(([k, type, ac], i) => `<label class="sx-field-in" for="df-${k}"><span>${esc(F.fields[i])}</span><input id="df-${k}" name="${k}" type="${type}" autocomplete="${ac}" maxlength="120"${k === 'town' ? ' list="df-towns"' : ''}${k === 'phone' ? ' inputmode="tel"' : ''}></label>`).join('');
  const checks = F.checks.map((c, i) => `<label class="sx-check-in"><input type="checkbox" name="sign" value="${i}"><span>${esc(c)}</span></label>`).join('');
  const meta = `<div class="sx-docmeta"><img src="${ctx.site.assets.logo}" width="120" height="68" alt="${esc(ctx.site.brand)}"><dl><div><dt>${lang === 'es' ? 'Versión' : 'Version'}</dt><dd>${DOC_VERSION}</dd></div><div><dt>${lang === 'es' ? 'Actualizado' : 'Updated'}</dt><dd>${DOC_DATE.split('-').reverse().join('/')}</dd></div><div><dt>Web</dt><dd>${CONTACT.web}</dd></div></dl></div>`;
  const strings = esc(JSON.stringify({ empty: t.empty, phoneBad: t.phoneBad, dateBad: t.dateBad, filename: t.filename, title: F.title, signs: t.signs, ask: t.msgAsk, labels: F.fields, checks: F.checks }));
  return `<section class="sx-block sx-detect" id="${id}" data-detect data-lang="${lang}" data-strings="${strings}">${meta}<h2 class="sx-detect-title">${esc(b.h2 || t.h)}</h2><p class="sx-tool-note sx-noprint">${esc(t.privacy)}</p>
<form class="sx-detect-form" novalidate><div class="sx-detect-grid">${fields}</div><datalist id="df-towns">${towns}</datalist><fieldset class="sx-detect-signs"><legend>${esc(t.signs)}</legend>${checks}</fieldset><p class="sx-detect-error sx-noprint" data-error role="alert" hidden></p>
<p class="sx-detect-note">${esc(F.note)}</p>
<div class="actions sx-noprint"><button type="button" class="button yellow" data-act="wa"><svg class="icon wa" aria-hidden="true"><use href="#icon-wa"/></svg>${esc(t.wa)}</button><button type="button" class="button" data-act="pdf">${esc(t.pdf)}</button><button type="button" class="button" data-act="share" hidden>${esc(t.share)}</button><button type="button" class="button" data-act="print">${esc(t.print)}</button><a class="button" href="${pdfHref(doc.file)}" download data-track="pdf_download">${esc(t.blank)}</a><button type="reset" class="button">${esc(t.reset)}</button></div></form>
<details class="sx-detect-help sx-noprint" open><summary>${esc(t.helpH)}</summary><ol>${t.help.map(x => `<li>${esc(x)}</li>`).join('')}</ol><p data-share-help hidden>${esc(t.helpShare)}</p><p>${esc(t.pbr)}</p></details></section>`;
}
